/usr/bin/bash -lc "python - <<'PY'
import re,collections,yaml,pathlib
p=pathlib.Path('candidate/statement-ledger.md');ls=p.read_text().splitlines(); rows=[]
for n,l in enumerate(ls,1):
 if n>831 and l.startswith('|'):
  cells=l.split('|')
  if len(cells)>3:
   ds=re.findall(r'"'`((?:StratonovichHAMSecondMoment|StratonovichHAMAudit)'"\\.["'^`]+)`'"',cells[2])
   for d in ds: rows.append((n,cells[1].strip(),d))
c=yaml.safe_load(pathlib.Path('lean/claims.yaml').read_text()); print('claims root',type(c),c.keys() if isinstance(c,dict) else '')
claims=c['claims'] if isinstance(c,dict) else c
cr={x['decl']:x for x in claims}; cnt=collections.Counter(x[2] for x in rows)
print('rows',len(rows),'unique',len(cnt),'by kind',collections.Counter(cr.get(x[2],{}).get('kind','MISSING') for x in rows))
print('labelled',sum(not x[1].startswith('no direct label') for x in rows),'unlabelled',sum(x[1].startswith('no direct label') for x in rows))
print('claims',len(claims),'kinds',collections.Counter(x['kind'] for x in claims)); print('missing rows', [x for x in cr if cnt[x]"'!=1]); print('"'extra',set(cnt)-set(cr))
v=yaml.safe_load(pathlib.Path('lean/coverage.yaml').read_text()); print('coverage class/conclusion',collections.Counter((r['class'],r.get('conclusion')) for r in v['rows']))
for label in ['L:phase-contractions','L:low-alpha-convolution']:
 r=next(r for r in v['rows'] if r['paper']['label']==label); print(label,'scope',r.get('conclusion_scope'),'inputs',r.get('inputs'),'missing claims',set(r['claims'])-set(x['id'] for x in claims))
labels=collections.defaultdict(list)
for f in pathlib.Path('manuscript').rglob('*.tex'):
 for n,l in enumerate(f.read_text().splitlines(),1):
  for lab in re.findall(r'\\\\label\\{(["'^}]+)'"\\}',l):labels[lab].append(f'{f}:{n}')
for lab in ['S:static-phase','L:phase-contractions','E:phase-resolvent','E:phase-trace','E:phase-constants','H:homog','L:low-alpha-convolution']:
 print(lab,labels[lab])
idx='\\n'.join(ls[430:828]); targets=[x for x in rows if x[2].startswith(('StratonovichHAMSecondMoment.PhaseContractions.','StratonovichHAMSecondMoment.L9Completed.'))]
print('targets',len(targets));print('index problems',[(x[2],idx.count('"'`'"'+x[2].split('.',1)[1]+'"'`'"')) for x in targets if idx.count('"'`'"'+x[2].split('.',1)[1]+'"'`'"')"'!=1])
PY'

